51	/// bootstrap) — never `sendMessage`.
52	class _FakeChatRepository implements ChatRepository {
53	  Either<Failure, List<ChatSession>> listSessionsResult = right([
54	    _sessionA,
55	    _sessionB,
56	  ]);
