93	/// Tiny standalone `GoRouter` — [AppDrawer] needs *some* router ancestor
94	/// to resolve `context.go(...)`, and — since spec-6-2 — a `ChatCubit`
95	/// ancestor too, provided here exactly the way `ChatScreen` provides it
96	/// in the real app (`BlocProvider<ChatCubit>.value`, Boundaries: "never a
97	/// second `sl<ChatCubit>()` inside `AppDrawer`"). This suite isn't
98	/// exercising the real app shell's redirect (that's `app_router_test.
99	/// dart`'s job).
100	GoRouter _buildTestRouter(ChatCubit cubit) {
101	  return GoRouter(
102	    initialLocation: '/',
103	    routes: [
104	      GoRoute(
105	        path: '/',
106	        builder: (context, state) => BlocProvider<ChatCubit>.value(
107	          value: cubit,
108	          child: const Scaffold(drawer: AppDrawer(), body: SizedBox.shrink()),
109	        ),
110	      ),
111	      GoRoute(
112	        path: '/meus-registros',
113	        builder: (context, state) => const Text('Meus Registros Screen'),
114	      ),
115	      GoRoute(
116	        path: '/planos-de-acao',
117	        builder: (context, state) => const Text('Planos Screen'),
118	      ),
119	      GoRoute(
120	        path: '/configuracoes',
121	        builder: (context, state) => const Text('Config Screen'),
122	      ),
123	    ],
124	  );
125	}
