132	/// spec-6-5 — every [ChatCubit] this suite constructs (the shared one
133	/// from `setUp()`, plus any test-local one) is tracked here and closed
134	/// from the local `testWidgets` override below, right after each test's
135	/// own body completes. A bootstrapped `ChatCubit` now always starts a
136	/// real `_insightInactivityTimer`; the ordinary `addTearDown`/group-level
137	/// `tearDown()` pattern this suite already uses for other cleanup runs
138	/// too late to satisfy `testWidgets`' own `!timersPending` invariant
139	/// check — that check runs *inside* the test's own callback execution,
140	/// before any `addTearDown`/`tearDown` callback ever fires, regardless of
141	/// whether the cubit (and its Timer) was created in `setUp()` or mid-test
142	/// (`close()` cancels either way, so tracking covers both).
143	final List<ChatCubit> _cubitsPendingClose = [];
144	
145	/// Wraps the real `testWidgets` so every test in this file automatically
146	/// closes every cubit [_cubitsPendingClose] collected during it.
147	void testWidgets(String description, WidgetTesterCallback callback) {
148	  flutter_test.testWidgets(description, (tester) async {
149	    try {
150	      await callback(tester);
151	    } finally {
152	      for (final cubit in _cubitsPendingClose) {
153	        await cubit.close();
154	      }
155	      _cubitsPendingClose.clear();
156	    }
157	  });
158	}
