162	/// section and its two entry points (`switchSession`/`startNewSession`),
163	/// driven through the exact `BlocProvider<ChatCubit>` instance the real
164	/// `ChatScreen` would provide.
165	void main() {
166	  late _FakeChatRepository fakeRepository;
167	  late FakeConnectivityWatcher fakeConnectivityWatcher;
168	  late ChatCubit cubit;
169	
170	  setUp(() async {
171	    fakeRepository = _FakeChatRepository();
172	    fakeConnectivityWatcher = FakeConnectivityWatcher();
173	    cubit = ChatCubit(
174	      fakeRepository,
175	      fakeConnectivityWatcher,
176	      UnusedSaveChatMessageAsEntryUseCase(),
177	    );
178	    await cubit.init();
179	    _cubitsPendingClose.add(cubit);
180	  });
181	
182	  tearDown(() async {
183	    await cubit.close();
184	    await fakeConnectivityWatcher.close();
185	  });
186	
