188	    'header shows a generic avatar + static label, no real identity',
189	    (tester) async {
190	      final router = _buildTestRouter(cubit);
191	      addTearDown(router.dispose);
192	      await tester.pumpWidget(MaterialApp.router(routerConfig: router));
193	      await _openDrawer(tester);
194	
195	      expect(find.text('Usuário'), findsOneWidget);
196	      expect(find.text('U'), findsOneWidget);
197	    },
198	  );
199	
200	  testWidgets('CONVERSAS section lists every bootstrapped session (title + '
201	      'timestamp), with an empty title falling back to "Nova conversa"', (
202	    tester,
203	  ) async {
204	    final router = _buildTestRouter(cubit);
205	    addTearDown(router.dispose);
206	    await tester.pumpWidget(MaterialApp.router(routerConfig: router));
207	    await _openDrawer(tester);
208	
209	    expect(find.text('CONVERSAS'), findsOneWidget);
210	    expect(find.text('Primeira conversa'), findsOneWidget);
211	    expect(find.text('Nova conversa'), findsOneWidget);
212	  });
213	
214	  testWidgets(
215	    'review finding: a session with a malformed updatedAt never crashes '
216	    'the CONVERSAS sort — it still renders, sorted defensively instead '
217	    'of throwing a FormatException',
218	    (tester) async {
219	      final crashFakeRepository = _FakeChatRepository();
220	      crashFakeRepository.listSessionsResult = right([
221	        _sessionA,
222	        const ChatSession(
223	          id: 'session-bad',
224	          title: 'Conversa corrompida',
225	          persona: ChatPersona.analitico,
226	          userMessageCount: 0,
227	          lastUserMessageAt: null,
228	          createdAt: 'not-a-date',
229	          updatedAt: 'not-a-date',
230	        ),
231	      ]);
232	      final crashCubit = ChatCubit(
233	        crashFakeRepository,
234	        FakeConnectivityWatcher(),
235	        UnusedSaveChatMessageAsEntryUseCase(),
236	      );
237	      _cubitsPendingClose.add(crashCubit);
238	      await crashCubit.init();
239	
240	      final router = _buildTestRouter(crashCubit);
241	      addTearDown(router.dispose);
242	      await tester.pumpWidget(MaterialApp.router(routerConfig: router));
243	      await _openDrawer(tester);
244	
245	      expect(tester.takeException(), isNull);
246	      expect(find.text('CONVERSAS'), findsOneWidget);
247	      expect(find.text('Primeira conversa'), findsOneWidget);
248	      expect(find.text('Conversa corrompida'), findsOneWidget);
249	    },
250	  );
251	
252	  testWidgets(
253	    'tapping a past session switches ChatCubit to it and closes the drawer',
254	    (tester) async {
255	      final router = _buildTestRouter(cubit);
256	      addTearDown(router.dispose);
257	      await tester.pumpWidget(MaterialApp.router(routerConfig: router));
258	      await _openDrawer(tester);
259	
260	      // Bootstrap reused session-b (most recent by updatedAt) — tap the
261	      // other one to switch away from it.
262	      expect((cubit.state as ChatReady).sessionId, 'session-b');
263	      await tester.tap(find.text('Primeira conversa'));
264	      await tester.pumpAndSettle();
265	
266	      expect(find.byType(AppDrawer), findsNothing);
267	      expect(router.state.uri.toString(), '/');
268	      expect((cubit.state as ChatReady).sessionId, 'session-a');
269	    },
270	  );
271	
272	  testWidgets(
273	    'tapping the already-active session is a no-op reload — drawer just '
274	    'closes, nothing else changes',
275	    (tester) async {
276	      final router = _buildTestRouter(cubit);
277	      addTearDown(router.dispose);
278	      await tester.pumpWidget(MaterialApp.router(routerConfig: router));
279	      await _openDrawer(tester);
280	
281	      expect((cubit.state as ChatReady).sessionId, 'session-b');
282	      await tester.tap(find.text('Nova conversa'));
283	      await tester.pumpAndSettle();
284	
285	      expect(find.byType(AppDrawer), findsNothing);
286	      expect((cubit.state as ChatReady).sessionId, 'session-b');
287	    },
288	  );
