290	  testWidgets('tapping "Novo Chat" while online creates and switches to a new, '
291	      'empty session, then closes the drawer', (tester) async {
292	    const created = ChatSession(
293	      id: 'session-new',
294	      title: '',
295	      persona: ChatPersona.analitico,
296	      userMessageCount: 0,
297	      lastUserMessageAt: null,
298	      createdAt: '2026-01-03T00:00:00Z',
299	      updatedAt: '2026-01-03T00:00:00Z',
300	    );
301	    fakeRepository.createSessionResult = right(created);
302	
303	    final router = _buildTestRouter(cubit);
304	    addTearDown(router.dispose);
305	    await tester.pumpWidget(MaterialApp.router(routerConfig: router));
306	    await _openDrawer(tester);
307	
308	    await tester.tap(find.text('Novo Chat'));
309	    await tester.pumpAndSettle();
310	
311	    expect(find.byType(AppDrawer), findsNothing);
312	    expect(router.state.uri.toString(), '/');
313	    final state = cubit.state as ChatReady;
314	    expect(state.sessionId, 'session-new');
315	    expect(state.messages, isEmpty);
316	  });
317	
318	  testWidgets('tapping "Novo Chat" while offline leaves the current session '
319	      'untouched, closes the drawer, and shows an error SnackBar (I/O '
320	      'matrix: "New session offline")', (tester) async {
321	    fakeRepository.createSessionResult = left(
322	      const Failure.networkOffline(message: 'Sem conexão'),
323	    );
324	
325	    final router = _buildTestRouter(cubit);
326	    addTearDown(router.dispose);
327	    await tester.pumpWidget(MaterialApp.router(routerConfig: router));
328	    await _openDrawer(tester);
329	
330	    final sessionIdBefore = (cubit.state as ChatReady).sessionId;
331	
332	    await tester.tap(find.text('Novo Chat'));
333	    await tester.pumpAndSettle();
334	
335	    expect(find.byType(AppDrawer), findsNothing);
336	    expect((cubit.state as ChatReady).sessionId, sessionIdBefore);
337	    expect(find.text('Sem conexão'), findsOneWidget);
338	  });
339	
340	  group('spec-6-3 — "Novo Chat" disables while ChatReady.isOffline', () {
341	    // Deliberately builds its own `ChatCubit`/`FakeConnectivityWatcher`
342	    // pair inside each test body below, rather than reusing the shared
343	    // `cubit`/`fakeConnectivityWatcher` the outer `setUp()` constructs —
344	    // `ChatCubit`'s constructor subscribes to the watcher's stream
345	    // immediately, and a subscription created inside an *async* `setUp()`
346	    // callback is registered in a different zone than the one
347	    // `tester.pumpAndSettle()` drains for a `testWidgets` body (a known
348	    // `flutter_test` gotcha: `setUp()`'s own async work runs outside
349	    // `TestWidgetsFlutterBinding`'s per-test zone), so a later
350	    // `watcher.emit(...)` call's effect on the widget tree would never be
351	    // observed by `pumpAndSettle()` within the test body. Constructing
352	    // both inside the test body itself keeps everything in the one zone
353	    // `pumpAndSettle()` actually watches.
354	    Future<({ChatCubit cubit, FakeConnectivityWatcher watcher})> boot(
355	      WidgetTester tester,
356	    ) async {
357	      final repository = _FakeChatRepository();
358	      final watcher = FakeConnectivityWatcher();
359	      final localCubit = ChatCubit(
360	        repository,
361	        watcher,
362	        UnusedSaveChatMessageAsEntryUseCase(),
363	      );
364	      await localCubit.init();
365	      _cubitsPendingClose.add(localCubit);
366	      addTearDown(watcher.close);
367	
368	      final router = _buildTestRouter(localCubit);
369	      addTearDown(router.dispose);
370	      await tester.pumpWidget(MaterialApp.router(routerConfig: router));
371	      await _openDrawer(tester);
372	      return (cubit: localCubit, watcher: watcher);
373	    }
374	
375	    InkWell novoChatInkWell(WidgetTester tester) => tester.widget<InkWell>(
376	      find.ancestor(of: find.text('Novo Chat'), matching: find.byType(InkWell)),
377	    );
378	
379	    Opacity novoChatOpacity(WidgetTester tester) => tester.widget<Opacity>(
380	      find.ancestor(of: find.text('Novo Chat'), matching: find.byType(Opacity)),
381	    );
382	
383	    testWidgets('"Novo Chat" disables (dimmed, no tap handler) once the '
384	        'ConnectivityWatcher reports offline', (tester) async {
385	      final booted = await boot(tester);
386	      expect(novoChatOpacity(tester).opacity, 1);
387	
388	      booted.watcher.emit(false);
389	      await tester.pumpAndSettle();
390	
391	      expect(novoChatOpacity(tester).opacity, lessThan(1));
392	      expect(novoChatInkWell(tester).onTap, isNull);
393	
394	      // Tapping it while disabled does nothing — never reaches
395	      // ChatCubit.startNewSession() at all.
396	      final sessionIdBefore = (booted.cubit.state as ChatReady).sessionId;
397	      await tester.tap(find.text('Novo Chat'));
398	      await tester.pumpAndSettle();
399	
400	      expect(find.byType(AppDrawer), findsOneWidget);
401	      expect((booted.cubit.state as ChatReady).sessionId, sessionIdBefore);
402	    });
403	
404	    testWidgets(
405	      '"Novo Chat" re-enables automatically once connectivity returns',
406	      (tester) async {
407	        final booted = await boot(tester);
408	
409	        booted.watcher.emit(false);
410	        await tester.pumpAndSettle();
411	        expect(novoChatInkWell(tester).onTap, isNull);
412	
413	        booted.watcher.emit(true);
414	        await tester.pumpAndSettle();
415	
416	        expect(novoChatInkWell(tester).onTap, isNotNull);
417	      },
418	    );
419	  });
420	
421	  testWidgets(
422	    'tapping "Meus Registros" closes the drawer and navigates there',
423	    (tester) async {
424	      final router = _buildTestRouter(cubit);
425	      addTearDown(router.dispose);
426	      await tester.pumpWidget(MaterialApp.router(routerConfig: router));
427	      await _openDrawer(tester);
428	
429	      await tester.tap(find.text('Meus Registros'));
430	      await tester.pumpAndSettle();
431	
432	      expect(find.byType(AppDrawer), findsNothing);
433	      expect(router.state.uri.toString(), '/meus-registros');
434	      expect(find.text('Meus Registros Screen'), findsOneWidget);
435	    },
436	  );
437	
438	  testWidgets(
439	    'tapping "Planos de Ação" closes the drawer and navigates there',
440	    (tester) async {
441	      final router = _buildTestRouter(cubit);
442	      addTearDown(router.dispose);
443	      await tester.pumpWidget(MaterialApp.router(routerConfig: router));
444	      await _openDrawer(tester);
445	
446	      await tester.tap(find.text('Planos de Ação'));
447	      await tester.pumpAndSettle();
448	
449	      expect(router.state.uri.toString(), '/planos-de-acao');
450	    },
451	  );
452	
453	  testWidgets('tapping "Configurações" closes the drawer and navigates there', (
454	    tester,
455	  ) async {
456	    final router = _buildTestRouter(cubit);
457	    addTearDown(router.dispose);
458	    await tester.pumpWidget(MaterialApp.router(routerConfig: router));
459	    await _openDrawer(tester);
460	
461	    await tester.tap(find.text('Configurações'));
462	    await tester.pumpAndSettle();
463	
464	    expect(router.state.uri.toString(), '/configuracoes');
465	  });
466	
467	  testWidgets('drawer width matches the design token', (tester) async {
468	    final router = _buildTestRouter(cubit);
469	    addTearDown(router.dispose);
470	    await tester.pumpWidget(MaterialApp.router(routerConfig: router));
471	    await _openDrawer(tester);
472	
473	    final drawer = tester.widget<Drawer>(find.byType(Drawer));
474	    expect(drawer.width, DesignTokens.drawerWidth);
475	  });
476	}
