264	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
265	    final args = call.arguments as Map<dynamic, dynamic>;
266	    switch (call.method) {
267	      case 'write':
268	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
269	        return null;
270	      case 'read':
271	        return fakeNativeStorage[args['key'] as String];
272	      case 'delete':
273	        fakeNativeStorage.remove(args['key'] as String);
274	        return null;
275	      case 'containsKey':
276	        return fakeNativeStorage.containsKey(args['key'] as String);
277	      default:
278	        return null;
279	    }
280	  }
