171	  Future<void> _bootstrap() async {
172	    emit(const ChatBootstrapLoading());
173	
174	    final sessionsResult = await _repository.listSessions();
175	    if (isClosed) {
176	      return;
177	    }
178	    // Captured by the closures below so the resulting [ChatReady] can
179	    // carry every known session (Code Map: "capture resolved sessions
180	    // into the emitted ChatReady"), not just the one picked to reuse.
181	    List<ChatSession> sessions = const [];
182	    final Either<Failure, ChatSession> sessionResult = await sessionsResult
183	        .match((failure) async => left(failure), (fetchedSessions) async {
184	          if (fetchedSessions.isEmpty) {
185	            final createResult = await _repository.createSession();
186	            return createResult.match((failure) => left(failure), (session) {
187	              sessions = [session];
188	              return right(session);
189	            });
190	          }
191	          sessions = fetchedSessions;
192	          // "reuse the most recent" — defensively re-sorts rather than
193	          // trusting `listSessions()`'s own ordering (its offline-cache
194	          // fallback already sorts `updatedAt` desc, but the live
195	          // server response's own ordering isn't documented either
196	          // way). `tryParse` (never `parse`) — same crash-safe pattern as
197	          // `AppDrawer`'s own session sort (review finding "Crash risk in
198	          // the new `_ConversasSection` sort"): a malformed `updatedAt`
199	          // must never crash bootstrap itself, so it falls back to the
200	          // epoch and simply sorts last instead of throwing.
201	          final mostRecent = [...fetchedSessions]
202	            ..sort(
203	              (a, b) => (DateTime.tryParse(b.updatedAt) ?? DateTime(0))
204	                  .compareTo(DateTime.tryParse(a.updatedAt) ?? DateTime(0)),
205	            );
206	          return right(mostRecent.first);
207	        });
208	    if (isClosed) {
209	      return;
210	    }
211	
212	    await sessionResult.match(
213	      (failure) async {
214	        if (!isClosed) {
215	          emit(ChatBootstrapError(failure));
216	        }
217	      },
218	      (session) async {
219	        final messagesResult = await _repository.listMessages(session.id);
220	        if (isClosed) {
221	          return;
222	        }
223	        messagesResult.match(
224	          (failure) => emit(ChatBootstrapError(failure)),
225	          (messages) {
226	            // spec-6-5 — opens this cubit's very first trigger window,
227	            // tied to the session this bootstrap settled on.
228	            _resetInsightWindow(session.id);
229	            emit(
230	              ChatReady(
231	                sessionId: session.id,
232	                messages: messages.map(_fromDomain).toList(),
233	                sessions: sessions,
234	                isOffline: _isOffline,
235	              ),
236	            );
237	          },
238	        );
239	      },
240	    );
241	  }
242	
243	  /// Boundaries: "Scroll-offset restore is in-memory only, keyed by
244	  /// `sessionId`" — `ChatScreen`'s own `ScrollController` listener calls
245	  /// this on every scroll update, so whichever offset a session was last
246	  /// left at is always the one [switchSession] hands back when that
247	  /// session becomes active again.
248	  void recordScrollOffset(String sessionId, double offset) {
249	    _scrollOffsets[sessionId] = offset;
250	  }
251	
252	  /// I/O matrix: "Switch session"/"Switch to already-active session" —
253	  /// a no-op [Right] when [sessionId] is already [ChatReady.sessionId]
254	  /// (the drawer still closes, nothing reloads/re-fetches); otherwise
255	  /// fetches that session's own history via `listMessages` (reused as-is,
256	  /// Code Map) and makes it active, handing [ChatReady.restoreScrollOffset]
257	  /// whatever [recordScrollOffset] last captured for it (`null` if this
258	  /// session was never scrolled in this app run — `ChatScreen`'s own cue
259	  /// to jump to the bottom instead). A no-op while bootstrap hasn't
260	  /// resolved yet, same guard shape as [sendMessage].
261	  Future<Either<Failure, Unit>> switchSession(String sessionId) async {
262	    final current = state;
263	    if (current is! ChatReady) {
264	      return right(unit);
265	    }
266	    if (sessionId == current.sessionId) {
267	      return right(unit);
268	    }
269	    // Review finding: "Cross-session stream leakage" — an AI response
270	    // still streaming into the *old* session must never be left running
271	    // once we switch away from it; its orphaned subscription's
272	    // `onData`/`onDone` would otherwise go on to mutate whichever session
273	    // becomes active next.
274	    await _cancelInFlightSend();
275	    final messagesResult = await _repository.listMessages(sessionId);
276	    if (isClosed) {
277	      return right(unit);
278	    }
279	    return messagesResult.match(
280	      (failure) {
281	        // Review fix: `_cancelInFlightSend()` above only resets the
282	        // internal `_isSending` guard, not the `ChatReady.isSending` the
283	        // composer gates on (`canSend = ... && !state.isSending`) — on a
284	        // failed switch we're staying on `current`, so its stale
285	        // `isSending: true` must be flipped back here or the composer
286	        // would stay disabled for the rest of the app run.
287	        if (!isClosed && current.isSending) {
288	          emit(current.copyWith(isSending: false));
289	        }
290	        return left(failure);
291	      },
292	      (messages) {
293	        if (!isClosed) {
294	          // spec-6-5 — reopens a fresh trigger window for the session
295	          // becoming active, so the previous session's own window
296	          // (counter/timer) never leaks across the switch (Boundaries).
297	          _resetInsightWindow(sessionId);
298	          emit(
299	            ChatReady(
300	              sessionId: sessionId,
301	              messages: messages.map(_fromDomain).toList(),
302	              sessions: current.sessions,
303	              restoreScrollOffset: _scrollOffsets[sessionId],
304	              isOffline: _isOffline,
305	            ),
306	          );
307	        }
308	        return right(unit);
309	      },
310	    );
311	  }
312	
313	  /// I/O matrix: "New session online"/"New session offline" — calls
314	  /// `createSession()` (reused as-is, Code Map; already blocked offline
315	  /// at the repository level, Boundaries). On any [Left] (including
316	  /// [Failure.networkOffline]), the current session is left completely
317	  /// untouched — no state is emitted at all, only the [Failure] is handed
318	  /// back for `AppDrawer` to surface as a transient `SnackBar`
319	  /// (Boundaries). On success, the new session opens empty and becomes
320	  /// active, prepended to [ChatReady.sessions].
321	  Future<Either<Failure, Unit>> startNewSession() async {
322	    final current = state;
323	    if (current is! ChatReady) {
324	      return right(unit);
325	    }
326	    // Review finding: "Cross-session stream leakage" — same rationale as
327	    // [switchSession]'s own cancellation above; a brand new session is
328	    // never the same session as [current], so this always needs to run
329	    // (unlike [switchSession], there's no same-session no-op branch to
330	    // skip it for).
331	    await _cancelInFlightSend();
332	    final result = await _repository.createSession();
333	    if (isClosed) {
334	      return right(unit);
335	    }
336	    return result.match(
337	      (failure) {
338	        // Review fix: same stuck-`isSending` risk as [switchSession] — a
339	        // failed `createSession()` leaves `current` active, so its stale
340	        // `isSending: true` (left behind by `_cancelInFlightSend()`
341	        // above, which never emits) must be flipped back here.
342	        if (!isClosed && current.isSending) {
343	          emit(current.copyWith(isSending: false));
344	        }
345	        return left(failure);
346	      },
347	      (session) {
348	        if (!isClosed) {
349	          // spec-6-5 — same rationale as [switchSession] above: a brand
350	          // new session always needs its own fresh trigger window.
351	          _resetInsightWindow(session.id);
352	          emit(
353	            ChatReady(
354	              sessionId: session.id,
355	              messages: const [],
356	              sessions: [session, ...current.sessions],
357	              isOffline: _isOffline,
358	            ),
359	          );
360	        }
361	        return right(unit);
362	      },
363	    );
364	  }
365	
366	  ChatUiMessage _fromDomain(ChatMessage message) => ChatUiMessage(
367	    id: message.id,
368	    role: message.role,
369	    content: message.content,
370	    status: message.status,
371	    // spec-6-3 — every message reloaded from `chat-messages-list`/the
372	    // offline cache already has a persisted server id (unlike a message
373	    // created locally mid-session, which only gains one once/if
374	    // `message_created` arrives, Design Notes); [retryMessage] reads this
375	    // off the *user* message immediately preceding a `failed` AI bubble.
376	    serverId: message.id,
377	    createdAt: message.createdAt,
378	    // Review fix (round 2) — re-applies a bookmark save's outcome that
379	    // resolved while this message wasn't part of the live `ChatReady`
380	    // (session switched away mid-save); `idle` default when nothing was
381	    // ever recorded for this `serverId`.
382	    bookmarkState:
383	        _bookmarkStateByServerId[message.id] ?? const BookmarkState.idle(),
384	  );
385	
386	  /// Boundaries: optimistic user bubble, then subscribes to
387	  /// `ChatRepository.sendMessage`'s own stream, appending tokens as they
388	  /// arrive and finalizing/failing the AI bubble on `done`/any `Left` —
389	  /// the bubble's own [ChatUiMessage.content] is never cleared on failure
390	  /// (I/O matrix), only its [ChatUiMessage.status] changes.
391	  ///
392	  /// A no-op while [state] isn't [ChatReady] (bootstrap still in flight
393	  /// or failed — the composer is disabled in that case anyway), while
394	  /// [content] is blank once trimmed, while [_isSending] is already
395	  /// true — this story never races two concurrent sends against the one
396	  /// in-memory session — or while [ChatReady.isOffline] (review finding:
397	  /// the offline lock was UI-only via `_ChatComposer.canSend`, but nothing
398	  /// stopped a direct `sendMessage` caller from firing a real network call
399	  /// while the offline banner's own "novas mensagens bloqueadas" copy says
400	  /// otherwise). Deliberately not keyed off any loaded message's
401	  /// persisted `streaming` status — a message restored from history/cache
402	  /// can legitimately carry that status without a send actually being in
403	  /// flight (I/O matrix: mid-stream drop).
404	  Future<void> sendMessage(String content) async {
405	    final trimmed = content.trim();
406	    if (trimmed.isEmpty) {
407	      return;
408	    }
409	    final current = state;
410	    if (current is! ChatReady) {
411	      return;
412	    }
413	    if (_isSending || current.isOffline) {
414	      return;
415	    }
416	    _isSending = true;
417	
418	    // spec-6-5 — counts only a genuine sendMessage() call (never
419	    // retryMessage, Boundaries: "a counter ... never retryMessage").
420	    // Whichever of the two trigger conditions is satisfied first wins
421	    // the race for this window; reaching the threshold here fires
422	    // immediately rather than waiting for the inactivity timer to also
423	    // elapse.
424	    _insightMessagesSinceWindowStart++;
425	    if (_insightMessagesSinceWindowStart >= insightMessageCountThreshold) {
426	      _fireInsightTrigger(current.sessionId, InsightTriggerType.messageCount);
427	    } else {
428	      // Counter/key untouched (Code Map) — only the inactivity side of
429	      // the race restarts, so the window itself stays open.
430	      _restartInsightInactivityTimer(current.sessionId);
431	    }
432	
433	    final userMessage = ChatUiMessage(
434	      id: _nextLocalId(),
435	      role: ChatMessageRole.user,
436	      content: trimmed,
437	      status: ChatMessageStatus.complete,
438	    );
439	    final aiMessage = ChatUiMessage(
440	      id: _nextLocalId(),
441	      role: ChatMessageRole.assistant,
442	      content: '',
443	      status: ChatMessageStatus.streaming,
444	    );
