459	  /// spec-6-3 — Boundaries: "Retry resets the *same* bubble (id,
460	  /// position) to `streaming`/empty, then reuses `_applyStreamEvent`/
461	  /// `_markFailed` unchanged — never a second bubble, never a duplicate
462	  /// question." [aiMessageId] must identify an existing `failed` AI
463	  /// bubble; anything else (not found, not `failed`, no preceding user
464	  /// message — shouldn't structurally happen) is a silent no-op, same
465	  /// defensive shape [sendMessage]'s own guards use.
466	  ///
467	  /// Keyed by the preceding user message's [ChatUiMessage.serverId]
468	  /// (Boundaries: "keyed by the user message's persisted id") — calls
469	  /// `ChatRepository.retryMessage` when it's known, or falls back to a
470	  /// full [ChatRepository.sendMessage] resend of that same user content
471	  /// into this exact AI bubble slot when it's `null` (I/O matrix: "Tap
472	  /// retry, no `serverId`" — the stream dropped before `message_created`
473	  /// ever arrived, so the backend never actually persisted the question;
474	  /// Boundaries: "Never calling `chat-messages-retry` with no `serverId`").
475	  /// Reuses [_isSending] verbatim (Boundaries: "A second retry while one
476	  /// is in flight"), so this is a no-op while a send/retry is already in
477	  /// flight — and, like [sendMessage] (review finding), a no-op while
478	  /// [ChatReady.isOffline] too: a failed bubble's retry tap is a separate
479	  /// affordance from the composer, not covered by `_ChatComposer.canSend`
480	  /// alone, so it needs this exact same guard to honor the offline banner.
481	  Future<void> retryMessage(String aiMessageId) async {
482	    final current = state;
483	    if (current is! ChatReady) {
484	      return;
485	    }
486	    if (_isSending || current.isOffline) {
487	      return;
488	    }
489	    final messages = current.messages;
490	    final aiIndex = messages.indexWhere((message) => message.id == aiMessageId);
491	    // Review finding: defensively checks `role` too, even though only an
492	    // assistant message ever reaches `failed` status today — matches this
493	    // guard clause's own already-defensive shape (`aiIndex == -1`, a
494	    // not-found/structurally-impossible case).
495	    if (aiIndex == -1 ||
496	        messages[aiIndex].role != ChatMessageRole.assistant ||
497	        messages[aiIndex].status != ChatMessageStatus.failed) {
498	      return;
499	    }
500	    ChatUiMessage? userMessage;
501	    for (var i = aiIndex - 1; i >= 0; i--) {
502	      if (messages[i].role == ChatMessageRole.user) {
503	        userMessage = messages[i];
504	        break;
505	      }
506	    }
507	    if (userMessage == null) {
508	      return;
509	    }
510	
511	    _isSending = true;
512	    emit(
513	      current.copyWith(
514	        messages: [
515	          for (final message in current.messages)
516	            if (message.id == aiMessageId)
517	              message.copyWith(content: '', status: ChatMessageStatus.streaming)
518	            else
519	              message,
520	        ],
521	        isSending: true,
522	      ),
523	    );
524	
525	    final serverId = userMessage.serverId;
526	    final stream = serverId == null
527	        ? _repository.sendMessage(current.sessionId, userMessage.content)
528	        : _repository.retryMessage(current.sessionId, serverId);
529	    await _consumeStream(
530	      stream,
531	      userMessageId: userMessage.id,
532	      aiMessageId: aiMessageId,
533	    );
534	  }
