536	  /// Shared by [sendMessage]/[retryMessage] (Code Map: "extract shared ...
537	  /// helper" extends to this subscribe-and-wait shape too, not just
538	  /// `ChatRemoteDataSource`'s own SSE buffering) — subscribes to [stream],
539	  /// routing every emission through [_applyStreamEvent]/[_markFailed], and
540	  /// resolves once the stream ends (`done`, an in-band error, or a
541	  /// stream-level error), clearing [_isSending]/[ChatReady.isSending]
542	  /// either way via [_finishSending].
543	  Future<void> _consumeStream(
544	    Stream<Either<Failure, ChatStreamEvent>> stream, {
545	    required String userMessageId,
546	    required String aiMessageId,
547	  }) async {
548	    await _sendSubscription?.cancel();
549	    final completer = Completer<void>();
550	    _sendCompleter = completer;
551	    _sendSubscription = stream.listen(
552	      (event) {
553	        event.match(
554	          (failure) => _markFailed(aiMessageId),
555	          (streamEvent) =>
556	              _applyStreamEvent(userMessageId, aiMessageId, streamEvent),
557	        );
558	      },
559	      onError: (Object _, StackTrace _) {
560	        // RNF09: no exception escapes the cubit — a stream-level error
561	        // (shouldn't happen, `ChatRemoteDataSource` never lets one through
562	        // unmapped) still only fails the bubble, never crashes.
563	        _markFailed(aiMessageId);
564	        _finishSending();
565	        if (!completer.isCompleted) {
566	          completer.complete();
567	        }
568	        // Review finding: a stale, already-done subscription reference
569	        // left on `_sendSubscription` made a *later* send/retry's own
570	        // `await _sendSubscription?.cancel()` above hang indefinitely in
571	        // practice (observed via a widget test driving two sends back to
572	        // back) — cleared here (and in the `onDone` branch below)
573	        // exactly where this stream's own lifecycle actually ends,
574	        // rather than relying on cancelling an already-finished
575	        // subscription being an instant no-op.
576	        _sendSubscription = null;
577	        _sendCompleter = null;
578	      },
579	      onDone: () {
580	        _finishSending();
581	        if (!completer.isCompleted) {
582	          completer.complete();
583	        }
584	        _sendSubscription = null;
585	        _sendCompleter = null;
586	      },
587	      cancelOnError: false,
588	    );
589	    await completer.future;
590	  }
