592	  /// Clears both the internal re-entrancy guard and the UI-facing
593	  /// [ChatReady.isSending] signal once a send's stream has ended (`done`,
594	  /// an in-band error, or a stream-level error) — the single place both
595	  /// flip back together.
596	  void _finishSending() {
597	    _isSending = false;
598	    if (isClosed) {
599	      return;
600	    }
601	    final current = state;
602	    if (current is ChatReady) {
603	      emit(current.copyWith(isSending: false));
604	    }
605	  }
