607	  void _applyStreamEvent(
608	    String userMessageId,
609	    String aiMessageId,
610	    ChatStreamEvent event,
611	  ) {
612	    if (isClosed) {
613	      return;
614	    }
615	    final current = state;
616	    if (current is! ChatReady) {
617	      return;
618	    }
619	    switch (event) {
620	      case ChatMessageCreatedEvent(userMessageId: final serverId):
621	        // spec-6-3 — Design Notes: "the persisted *user*-message id" is
622	        // now this story's first consumer, captured onto the matching
623	        // local user bubble by id so a later `retryMessage` call (on the
624	        // AI bubble this same send produces) has a non-null `serverId` to
625	        // key `chat-messages-retry` off of.
626	        emit(
627	          current.copyWith(
628	            messages: [
629	              for (final message in current.messages)
630	                if (message.id == userMessageId)
631	                  message.copyWith(serverId: serverId)
632	                else
633	                  message,
634	            ],
635	          ),
636	        );
637	      case ChatTokenEvent(delta: final delta):
638	        emit(
639	          current.copyWith(
640	            messages: [
641	              for (final message in current.messages)
642	                if (message.id == aiMessageId)
643	                  message.copyWith(content: message.content + delta)
644	                else
645	                  message,
646	            ],
647	          ),
648	        );
649	      case ChatDoneEvent():
650	        emit(
651	          current.copyWith(
652	            messages: [
653	              for (final message in current.messages)
654	                if (message.id == aiMessageId)
655	                  message.copyWith(status: ChatMessageStatus.complete)
656	                else
657	                  message,
658	            ],
659	          ),
660	        );
661	    }
662	  }
