688	  /// spec-6-4 (RF10) — Boundaries: the bookmark affordance exists only on
689	  /// [ChatMessageRole.user] bubbles; tapping it turns that exact message
690	  /// into a journal Entry (`source: EntrySource.chat`) through
691	  /// [_saveChatMessageAsEntryUseCase] only — never `EntriesRepository`
692	  /// directly (AGENTS.md's RF10 rule). A no-op (I/O & Edge-Case Matrix)
693	  /// when: [state] isn't [ChatReady]; [messageId] isn't found; its role
694	  /// isn't [ChatMessageRole.user]; its [ChatUiMessage.serverId] is still
695	  /// `null` (mirrors [retryMessage]'s own guard — the backend id a save
696	  /// sends as `chatMessageId`, Boundaries); its [ChatUiMessage.
697	  /// bookmarkState] is already [BookmarkSaved] (client-side no-op — a
698	  /// repeat save is itself idempotent at the backend, Boundaries) or
699	  /// already [BookmarkSaving] (re-entrancy guard, scoped to this one
700	  /// message — [_isSending] stays scoped to send/retry only, never shared
701	  /// with this guard).
702	  Future<void> bookmarkMessage(String messageId) async {
703	    final current = state;
704	    if (current is! ChatReady) {
705	      return;
706	    }
707	    final index = current.messages.indexWhere(
708	      (message) => message.id == messageId,
709	    );
710	    if (index == -1) {
711	      return;
712	    }
713	    final message = current.messages[index];
714	    final serverId = message.serverId;
715	    if (message.role != ChatMessageRole.user ||
716	        serverId == null ||
717	        message.bookmarkState is BookmarkSaved ||
718	        message.bookmarkState is BookmarkSaving) {
719	      return;
720	    }
721	
722	    // Boundaries: both of this method's own emit() calls check isClosed
723	    // first — not just the one after the await below.
724	    if (isClosed) {
725	      return;
726	    }
727	    _bookmarkStateByServerId[serverId] = const BookmarkState.saving();
728	    emit(
729	      current.copyWith(
730	        messages: [
731	          for (final existing in current.messages)
732	            if (existing.id == messageId)
733	              existing.copyWith(bookmarkState: const BookmarkState.saving())
734	            else
735	              existing,
736	        ],
737	      ),
738	    );
739	
740	    final sideEffectResult = await isolatedSideEffect(
741	      () => _saveChatMessageAsEntry(
742	        content: message.content,
743	        chatMessageId: serverId,
744	      ),
745	    );
746	    // Flattens isolatedSideEffect's own outer Either (Left only on a
747	    // thrown exception, mapped to malformedResponse — I/O matrix: "Side-
748	    // effect throws") with the use case's own inner Either (Left on a
749	    // normal, non-thrown save failure — I/O matrix: "Save fails") into
750	    // one plain Either<Failure, Entry>, so both scenarios flip the bubble
751	    // to the same retryable error state via the one match() below.
752	    final result = sideEffectResult.match(
753	      (failure) => left(failure),
754	      (inner) => inner,
755	    );
756	
757	    final resolvedState = result.match(
758	      (failure) => BookmarkState.error(failure),
759	      (_) => const BookmarkState.saved(),
760	    );
761	    // Review fix (round 2) — written through to the serverId-keyed map
762	    // unconditionally (even if the live [ChatReady] below has since moved
763	    // on to a different session), so the outcome is never lost; re-
764	    // entering any session carrying this message picks it back up via
765	    // [_fromDomain].
766	    _bookmarkStateByServerId[serverId] = resolvedState;
767	
768	    if (isClosed) {
769	      return;
770	    }
771	    final latest = state;
772	    if (latest is! ChatReady) {
773	      return;
774	    }
775	    // Matched by `serverId`, not the in-session `messageId` — the latter
776	    // is stale once [switchSession]/[startNewSession] reloads this exact
777	    // session's history mid-save, which re-derives every message's own
778	    // `id` from the server (`_fromDomain`) instead of keeping the local
779	    // id this call started with.
780	    final stillVisible = latest.messages.any(
781	      (existing) => existing.serverId == serverId,
782	    );
783	    if (!stillVisible) {
784	      return;
785	    }
786	    emit(
787	      latest.copyWith(
788	        messages: [
789	          for (final existing in latest.messages)
790	            if (existing.serverId == serverId)
791	              existing.copyWith(bookmarkState: resolvedState)
792	            else
793	              existing,
794	        ],
795	      ),
796	    );
797	  }
