982	    _connectivitySubscription?.cancel();
983	    _sendSubscription?.cancel();
984	    // spec-6-5 — a closed cubit must never let a pending trigger fire
985	    // into a dead instance.
986	    _insightInactivityTimer?.cancel();
987	    final completer = _sendCompleter;
988	    if (completer != null && !completer.isCompleted) {
989	      completer.complete();
990	    }
991	    _sendCompleter = null;
992	    return super.close();
993	  }
994	}
