1	part of 'bloc.dart';
2	
3	/// An object that provides access to a stream of states over time.
4	abstract class Streamable<State extends Object?> {
5	  /// The current [stream] of states.
6	  Stream<State> get stream;
7	}
8	
9	/// A [Streamable] that provides synchronous access to the current [state].
10	abstract class StateStreamable<State> implements Streamable<State> {
11	  /// The current [state].
12	  State get state;
13	}
14	
15	/// A [StateStreamable] that must be closed when no longer in use.
16	abstract class StateStreamableSource<State>
17	    implements StateStreamable<State>, Closable {}
18	
19	/// An object that must be closed when no longer in use.
20	abstract class Closable {
21	  /// Closes the current instance.
22	  /// The returned future completes when the instance has been closed.
23	  FutureOr<void> close();
24	
25	  /// Whether the object is closed.
26	  ///
27	  /// An object is considered closed once [close] is called.
28	  bool get isClosed;
29	}
30	
31	/// An object that can emit new states.
32	// ignore: one_member_abstracts
33	abstract class Emittable<State extends Object?> {
34	  /// Emits a new [state].
35	  void emit(State state);
36	}
37	
38	/// A generic destination for errors.
39	///
40	/// Multiple errors can be reported to the sink via `addError`.
41	abstract class ErrorSink implements Closable {
42	  /// Adds an [error] to the sink with an optional [stackTrace].
43	  ///
44	  /// Must not be called on a closed sink.
45	  void addError(Object error, [StackTrace? stackTrace]);
46	}
47	
48	/// A [StateStreamableSource] that can emit new states.
49	abstract class EmittableStateStreamableSource<State>
50	    implements StateStreamableSource<State>, Emittable<State> {}
51	
52	/// {@template bloc_base}
53	/// An interface for the core functionality implemented by
54	/// both [Bloc] and [Cubit].
55	/// {@endtemplate}
56	abstract class BlocBase<State>
57	    implements EmittableStateStreamableSource<State>, ErrorSink {
58	  /// {@macro bloc_base}
59	  BlocBase(this._state) {
60	    // ignore: invalid_use_of_protected_member
61	    _blocObserver.onCreate(this);
62	  }
63	
64	  final _blocObserver = Bloc.observer;
65	
66	  late final _stateController = StreamController<State>.broadcast();
67	
68	  State _state;
69	
70	  bool _emitted = false;
71	
72	  @override
73	  State get state => _state;
74	
75	  @override
76	  Stream<State> get stream => _stateController.stream;
77	
78	  /// Whether the bloc is closed.
79	  ///
80	  /// A bloc is considered closed once [close] is called.
81	  /// Subsequent state changes cannot occur within a closed bloc.
82	  @override
83	  bool get isClosed => _stateController.isClosed;
84	
85	  /// Updates the [state] to the provided [state].
86	  /// [emit] does nothing if the [state] being emitted
87	  /// is equal to the current [state].
88	  ///
89	  /// To allow for the possibility of notifying listeners of the initial state,
90	  /// emitting a state which is equal to the initial state is allowed as long
91	  /// as it is the first thing emitted by the instance.
92	  ///
93	  /// * Throws a [StateError] if the bloc is closed.
94	  @protected
95	  @visibleForTesting
96	  @override
97	  void emit(State state) {
98	    try {
99	      if (_stateController.isClosed) {
100	        throw StateError('Cannot emit new states after calling close');
101	      }
102	      if (state == _state && _emitted) return;
103	      onChange(Change<State>(currentState: this.state, nextState: state));
104	      _state = state;
105	      _stateController.add(_state);
106	      _emitted = true;
107	    } catch (error, stackTrace) {
108	      onError(error, stackTrace);
109	      rethrow;
110	    }
