        // ignore: avoid_print
        print('DEBUG closing cubit, isClosed=${cubit.isClosed}');
        await cubit.close();
        // ignore: avoid_print
        print('DEBUG cubit closed');
      }
      _cubitsPendingClose.clear();
    }
  });
